func newBulkEdit() unsafe.Pointer { return unsafe.Pointer(new(bulkedit.BulkEdit)) }

func newNBulkEdit(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]bulkedit.BulkEdit, n)))
}

func ptrBulkEdit(p unsafe.Pointer, c int32) any {
	r := (*bulkedit.BulkEdit)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return &r.Resource
	case 5:
		return &r.Field
	case 6:
		return &r.Value
	case 7:
		return &r.Selection
	case 8:
		return &r.Targets
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return (*int64)(unsafe.Pointer(&r.TotalCount))
	case 11:
		return (*int64)(unsafe.Pointer(&r.ChangedCount))
	case 12:
		return (*int64)(unsafe.Pointer(&r.FailedCount))
	case 13:
		return (*int64)(unsafe.Pointer(&r.ProcessedCount))
	case 14:
		return &r.FailureMessage
	case 15:
		return &r.CompletedAt
	case 16:
		return &r.UndoneAt
	case 17:
		return &r.Version
	case 18:
		return &r.CreatedAt
	case 19:
		return &r.UpdatedAt
	}
	return nil
}

func valueBulkEdit(p unsafe.Pointer, c int32) any {
	r := (*bulkedit.BulkEdit)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.UserID)
	case 4:
		return r.Resource
	case 5:
		return r.Field
	case 6:
		return r.Value
	case 7:
		return r.Selection
	case 8:
		if r.Targets == nil {
			return keel.EmptyJSONArray
		}
		return r.Targets
	case 9:
		return string(r.Status)
	case 10:
		return int64(r.TotalCount)
	case 11:
		return int64(r.ChangedCount)
	case 12:
		return int64(r.FailedCount)
	case 13:
		return int64(r.ProcessedCount)
	case 14:
		return r.FailureMessage
	case 15:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 16:
		if r.UndoneAt == nil {
			return nil
		}
		return *r.UndoneAt
	case 17:
		return r.Version
	case 18:
		return r.CreatedAt
	case 19:
		return r.UpdatedAt
	}
	return nil
}

func attachBulkEdit(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*bulkedit.BulkEdit)(p)
	switch rel {
	case 0:
		r.User = (*tenant.User)(child)
	}
}

func init() {
	bulkEditsTable.Relations[0].Target = tenantdb.UsersSchema()
}

